          texto:
            "En el centro del libro, Sócrates suelta lo que él mismo llama la tercera ola, la más ridícula de sus propuestas, la que teme que le cueste que lo echen a pedradas: que mientras los filósofos no gobiernen o los gobernantes no filosofen, no habrá fin de los males.",
